'use strict';
(()=>{let last='';const mounted=new WeakSet();async function mount(){const id=location.hash.match(/^#virus\/([^/]+)$/)?.[1],target=document.querySelector('#research-tracker');if(!id||!target){last='';return}if(mounted.has(target))return;mounted.add(target);last=id;const section=document.createElement('section');section.className='published-reviews';const h=document.createElement('h2');h.textContent='人工审核的基础说明 / Reviewed notes';section.append(h);target.after(section);try{const r=await fetch('/api/reviews/published?id='+encodeURIComponent(id));if(!r.ok)throw Error();const d=await r.json();if(!d.items.length){section.remove();return}for(const x of d.items){const a=document.createElement('article');for(const text of [x.summaryZh,x.summaryEn,'Highlights: '+(x.highlightsZh||'')+' '+(x.highlightsEn||''),'证据 / Evidence: '+x.evidence+' · 阅读范围 / Reading: '+x.level,x.limits,'来源位置 / Source location: '+x.location,'发布 / Published: '+x.at]){const p=document.createElement('p');p.textContent=text;a.append(p)}const link=document.createElement('a');link.textContent=x.paper.title;link.href=x.paper.url;link.target='_blank';link.rel='noopener noreferrer';a.append(link);section.append(a)}}catch{section.remove();last=''}}new MutationObserver(()=>{mount()}).observe(document.body,{childList:true,subtree:true});mount()})();
